<div class="category-tree-row <?= (int)$this->selected===(int)$row['id']?'is-selected':'' ?>" data-tree-row><div class="tree-category-name"><button type="button" class="tree-drag-handle" data-drag-category="<?= (int)$row['id'] ?>" aria-label="جابه‌جایی <?= CHtml::encode($row['name']) ?>" title="برای جابه‌جایی بکشید">⠿</button><button type="button" class="tree-toggle" data-toggle-branch aria-label="باز یا بسته کردن زیرمجموعه‌ها" aria-expanded="true">⌄</button><a href="<?= CHtml::encode(Yii::app()->createUrl('adminCategory/index',array('id'=>$row['id']))) ?>" data-pjax="1" data-pjax-target="#category-editor" data-pjax-reset-scroll="1" class="category-edit-link"><strong><?= CHtml::encode($row['name']) ?></strong><small dir="ltr"><?= CHtml::encode($row['slug']) ?></small></a></div><span class="tree-category-thumbnail"><?php if(!empty($row['image']))echo MediaService::responsive($row['image'],$row['name'],array('loading'=>'lazy','sizes'=>'40px')); ?></span><span class="tree-product-count"><?= number_format($products[$row['id']]??0) ?></span><div class="tree-row-actions"><button type="button" data-tree-step="before" aria-label="انتقال به بالا" title="بالا">↑</button><button type="button" data-tree-step="after" aria-label="انتقال به پایین" title="پایین">↓</button></div></div></div><?php endforeach; ?>
</div><?php if(!$rows): ?><p class="empty">هنوز دسته‌ای ساخته نشده است؛ از فرم کنار صفحه اضافه کنید.</p><?php endif; ?>
